import re

from langflow.custom import Component
from langflow.io import BoolInput, DropdownInput, IntInput, MessageInput, MessageTextInput, Output
from langflow.schema.message import Message


class ConditionalRouterComponent(Component):
    display_name = "If-Else"
    description = "Routes an input message to a corresponding output based on text comparison."
    icon = "split"
    name = "ConditionalRouter"

    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)
        self.__iteration_updated = False

    inputs = [
        MessageTextInput(
            name="input_text",
            display_name="Text Input",
            info="The primary text input for the operation.",
            required=True,
        ),
        MessageTextInput(
            name="match_text",
            display_name="Match Text",
            info="The text input to compare against.",
            required=True,
        ),
        DropdownInput(
            name="operator",
            display_name="Operator",
            options=["equals", "not equals", "contains", "starts with", "ends with", "regex"],
            info="The operator to apply for comparing the texts.",
            value="equals",
            real_time_refresh=True,
        ),
        BoolInput(
            name="case_sensitive",
            display_name="Case Sensitive",
            info="If true, the comparison will be case sensitive.",
            value=False,
        ),
        MessageInput(
            name="message",
            display_name="Message",
            info="The message to pass through either route.",
        ),
        IntInput(
            name="max_iterations",
            display_name="Max Iterations",
            info="The maximum number of iterations for the conditional router.",
            value=10,
            advanced=True,
        ),
        DropdownInput(
            name="default_route",
            display_name="Default Route",
            options=["true_result", "false_result"],
            info="The default route to take when max iterations are reached.",
            value="false_result",
            advanced=True,
        ),
    ]

    outputs = [
        Output(display_name="True", name="true_result", method="true_response"),
        Output(display_name="False", name="false_result", method="false_response"),
    ]

    def _pre_run_setup(self):
        self.__iteration_updated = False

    def evaluate_condition(self, input_text: str, match_text: str, operator: str, *, case_sensitive: bool) -> bool:
        if not case_sensitive and operator != "regex":
            input_text = input_text.lower()
            match_text = match_text.lower()

        if operator == "equals":
            return input_text == match_text
        if operator == "not equals":
            return input_text != match_text
        if operator == "contains":
            return match_text in input_text
        if operator == "starts with":
            return input_text.startswith(match_text)
        if operator == "ends with":
            return input_text.endswith(match_text)
        if operator == "regex":
            try:
                return bool(re.match(match_text, input_text))
            except re.error:
                return False  # Return False if the regex is invalid
        return False

    def iterate_and_stop_once(self, route_to_stop: str):
        if not self.__iteration_updated:
            self.update_ctx({f"{self._id}_iteration": self.ctx.get(f"{self._id}_iteration", 0) + 1})
            self.__iteration_updated = True
            if self.ctx.get(f"{self._id}_iteration", 0) >= self.max_iterations and route_to_stop == self.default_route:
                route_to_stop = "true_result" if route_to_stop == "false_result" else "false_result"
            self.stop(route_to_stop)

    def true_response(self) -> Message:
        result = self.evaluate_condition(
            self.input_text, self.match_text, self.operator, case_sensitive=self.case_sensitive
        )
        if result:
            self.status = self.message
            self.iterate_and_stop_once("false_result")
            return self.message
        self.iterate_and_stop_once("true_result")
        return Message(content="")

    def false_response(self) -> Message:
        result = self.evaluate_condition(
            self.input_text, self.match_text, self.operator, case_sensitive=self.case_sensitive
        )
        if not result:
            self.status = self.message
            self.iterate_and_stop_once("true_result")
            return self.message
        self.iterate_and_stop_once("false_result")
        return Message(content="")

    def update_build_config(self, build_config: dict, field_value: str, field_name: str | None = None) -> dict:
        if field_name == "operator":
            if field_value == "regex":
                build_config.pop("case_sensitive", None)

            # Ensure case_sensitive is present for all other operators
            elif "case_sensitive" not in build_config:
                case_sensitive_input = next(
                    (input_field for input_field in self.inputs if input_field.name == "case_sensitive"), None
                )
                if case_sensitive_input:
                    build_config["case_sensitive"] = case_sensitive_input.to_dict()
        return build_config

from contextlib import contextmanager
import pandas as pd
import re
from googleapiclient.discovery import build
from googleapiclient.errors import HttpError
from langflow.custom import Component
from langflow.inputs import MessageTextInput, SecretStrInput
from langflow.schema import DataFrame
from langflow.template import Output
from youtube_transcript_api import YouTubeTranscriptApi, TranscriptsDisabled, VideoUnavailable, NoTranscriptFound


class YouTubeTranscriptComponent(Component):
    """A component that retrieves transcripts from YouTube videos, supporting Tamil and English."""

    display_name: str = "YouTube Transcript"
    description: str = "Fetches transcripts from YouTube videos, including Tamil language."
    icon: str = "YouTube"

    inputs = [
        MessageTextInput(
            name="video_url",
            display_name="Video URL",
            info="Enter the YouTube video URL.",
            tool_mode=True,
            required=True,
        ),
        SecretStrInput(
            name="api_key",
            display_name="YouTube API Key",
            info="Enter your YouTube Data API key.",
            required=True,
        ),
    ]

    outputs = [
        Output(name="transcript", display_name="Transcript", method="get_video_transcript"),
    ]

    def _extract_video_id(self, video_url: str) -> str:
        """Extracts the video ID from a YouTube URL."""
        patterns = [
            r"(?:youtube\.com\/watch\?v=|youtu\.be\/|youtube\.com\/embed\/|youtube\.com\/v\/|youtube\.com\/live\/)([^&\n?#]+)",
            r"youtube\.com\/shorts\/([^&\n?#]+)",
        ]
        
        for pattern in patterns:
            match = re.search(pattern, video_url)
            if match:
                return match.group(1)
        
        return None  # Return None if no valid video ID is found

    @contextmanager
    def youtube_client(self):
        """Context manager for YouTube API client."""
        if not self.api_key:
            raise ValueError("YouTube API key is missing.")

        client = build("youtube", "v3", developerKey=self.api_key)
        try:
            yield client
        finally:
            client.close()

    def get_video_details(self, video_id: str) -> str:
        """Fetches the video title using YouTube Data API."""
        try:
            with self.youtube_client() as client:
                response = client.videos().list(
                    part="snippet",
                    id=video_id
                ).execute()

                if response["items"]:
                    return response["items"][0]["snippet"]["title"]
                else:
                    return "Unknown Title"

        except HttpError as e:
            return f"YouTube API error: {e}"

    def get_video_transcript(self) -> DataFrame:
        """Fetches the transcript of a YouTube video, prioritizing Tamil language."""
        video_id = self._extract_video_id(self.video_url)
        if not video_id:
            return DataFrame(pd.DataFrame({"error": ["Invalid YouTube URL."]}))

        try:
            # Try fetching transcript in Tamil first, then English, then auto-generated
            transcript_data = None
            languages = ["ta", "en", "en-US", "en-GB"]  # Tamil first, then English variants
            
            for lang in languages:
                try:
                    transcript_data = YouTubeTranscriptApi.get_transcript(video_id, languages=[lang])
                    if transcript_data:
                        break  # Stop once a valid transcript is found
                except NoTranscriptFound:
                    continue  # Try the next language if transcript is unavailable
            
            # If no official transcript is found, try auto-generated transcripts
            if not transcript_data:
                try:
                    transcript_data = YouTubeTranscriptApi.get_transcript(video_id)  # Auto-generated
                except NoTranscriptFound:
                    pass  # Still no transcript available

            if not transcript_data:
                return DataFrame(pd.DataFrame({"error": ["No transcript found in Tamil or English."]}))

            full_transcript = " ".join([entry["text"] for entry in transcript_data])
            
            # Fetch video title
            video_title = self.get_video_details(video_id)

            # Return as DataFrame
            return DataFrame(pd.DataFrame({
                "video_id": [video_id],
                "video_title": [video_title],
                "video_url": [self.video_url],
                "transcript": [full_transcript],
            }))

        except TranscriptsDisabled:
            return DataFrame(pd.DataFrame({"error": ["Transcripts are disabled for this video."]}))

        except VideoUnavailable:
            return DataFrame(pd.DataFrame({"error": ["This video is either private, removed, or unavailable."]}))

        except HttpError as e:
            return DataFrame(pd.DataFrame({"error": [f"YouTube API error: {e}"]}))

        except Exception as e:
            return DataFrame(pd.DataFrame({"error": [f"Unexpected error: {e}"]}))
